+  });
+  const next = applyTaskOccurrenceAction(task, {
+    action: "complete",
+    actedAt: "2026-08-15T12:00:00.000Z",
+    actedOnDate: "2026-08-15",
+  });
+
+  assert.equal(next.scheduledDate, "2026-08-29");
+  assert.equal(next.occurrences.length, 1);
+});
